package com.parion.aidat;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class MainActivityV23 extends MainActivityV222 {
 int SOFT=Color.rgb(250,248,240),DARK=Color.rgb(32,32,32),LINE=Color.rgb(225,225,225),GREEN=Color.rgb(30,130,70);
 @Override public void onCreate(android.os.Bundle b){super.onCreate(b);try{db.ensureV23();}catch(Exception e){}}
 GradientDrawable box(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));g.setStroke(dp(1),LINE);return g;}
 TextView row(String label,String value,boolean alt){TextView t=tv(label+":  "+(value==null||value.isEmpty()?"—":value),14,false);t.setBackground(box(alt?Color.rgb(244,244,244):Color.WHITE,8));t.setPadding(dp(12),dp(11),dp(12),dp(11));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(2),0,dp(2));t.setLayoutParams(p);return t;}
 Button menu(String s){Button b=btn(s);b.setTextSize(17);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(dp(18),0,dp(12),0);b.setBackground(box(Color.WHITE,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(62));p.setMargins(0,dp(5),0,dp(5));b.setLayoutParams(p);return b;}
 void section(String title){TextView h=tv(title,18,true);h.setTextColor(DARK);h.setPadding(dp(4),dp(18),dp(4),dp(7));content.addView(h);}
 @Override void dashboard(){screen="HOME";clear();content.setBackgroundColor(SOFT);ImageView logo=new ImageView(this);logo.setImageResource(com.parion.aidat.R.drawable.parion_logo);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);content.addView(logo,new LinearLayout.LayoutParams(-1,dp(150)));TextView title=tv("PARİON SPOR KULÜBÜ",24,true);title.setGravity(Gravity.CENTER);content.addView(title);TextView sum=tv("BU AY BEKLENEN  "+tl(db.expectedTotal(year,month))+"   •   TAHSİL  "+tl(db.collected(year,month)),13,true);sum.setGravity(Gravity.CENTER);sum.setBackground(box(Color.WHITE,10));content.addView(sum);String[] names={"1. SPORCU","2. AİDAT","3. YOKLAMALAR","4. STOKLAR","5. GÜNCELLEMELER"};for(int i=0;i<names.length;i++){final int x=i;Button b=menu(names[i]);b.setOnClickListener(v->{push(()->dashboard());if(x==0)athleteMenu();else if(x==1)duesMenu();else if(x==2){now();attendanceGroups();}else if(x==3)inventoryScreen();else updatesMenu();});content.addView(b);}}
 void athleteMenu(){screen="ATHMENU";clear();heading("SPORCU");EditText q=field("SPORCU ARA",1);q.setBackground(box(Color.WHITE,10));content.addView(q,new LinearLayout.LayoutParams(-1,dp(58)));LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);content.addView(results);q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){results.removeAllViews();String z=up(s.toString().trim());if(z.length()<2)return;Cursor cur=db.searchAthletes(z);while(cur.moveToNext()){long id=cur.getLong(cur.getColumnIndexOrThrow("id"));Button r=btn(val(cur,"name")+" • "+val(cur,"groupName"));r.setOnClickListener(v->{push(()->athleteMenu());athleteDetail(id);});results.addView(r);}cur.close();}});Button n=menu("2. YENİ KAYIT");n.setOnClickListener(v->{push(()->athleteMenu());athleteForm(0);});content.addView(n);Button e=menu("3. SPORCU GÜNCELLE");e.setOnClickListener(v->{push(()->athleteMenu());searchScreen(true);});content.addView(e);Button d=menu("4. SPORCU SİL");d.setOnClickListener(v->{push(()->athleteMenu());deleteSearch();});content.addView(d);}
 void duesMenu(){screen="DUESMENU";clear();heading("AİDAT");Button a=menu("1. AİDAT TAKİP");a.setOnClickListener(v->{now();push(()->duesMenu());feeScreen();});content.addView(a);Button b=menu("2. AİDAT GÜNCELLE");b.setOnClickListener(v->{push(()->duesMenu());paymentAthleteSearch();});content.addView(b);}
 void updatesMenu(){screen="UPDATES";clear();heading("GÜNCELLEMELER");Button a=menu("1. AİDAT MİKTARINI GÜNCELLE");a.setOnClickListener(v->{push(()->updatesMenu());bulkFeeScreen();});content.addView(a);Button g=menu("2. GRUPLAR");g.setOnClickListener(v->{push(()->updatesMenu());groupsScreen();});content.addView(g);}
 void deleteSearch(){screen="DELETE";clear();heading("SPORCU SİL");EditText q=field("SİLİNECEK SPORCUYU ARA",1);content.addView(q);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);content.addView(r);q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){r.removeAllViews();if(s.length()<2)return;Cursor x=db.searchAthletes(up(s.toString()));while(x.moveToNext()){long id=x.getLong(x.getColumnIndexOrThrow("id"));String name=val(x,"name");Button deleteBtn=btn(name);deleteBtn.setOnClickListener(v->new AlertDialog.Builder(MainActivityV23.this).setTitle("SPORCU SİL").setMessage("SEÇİLEN SPORCU VERİTABANINDAN SİLİNSİN Mİ?\n\n"+name).setPositiveButton("EVET",(d,w)->{db.deleteAthleteCascade(id);toast("SPORCU SİLİNDİ");deleteSearch();}).setNegativeButton("HAYIR",null).show());r.addView(deleteBtn);}x.close();}});}
 @Override void athleteDetail(long id){screen="DETAIL";clear();heading("SPORCU PROFİLİ");Cursor c=db.athlete(id);if(!c.moveToFirst()){c.close();return;}TextView name=tv(val(c,"name"),24,true);name.setGravity(Gravity.CENTER);content.addView(name);String uri=val(c,"photoUri");ZoomImage im=new ZoomImage(this);im.setScaleType(ImageView.ScaleType.FIT_CENTER);if(!uri.isEmpty())try{im.setImageURI(Uri.parse(uri));}catch(Exception e){}content.addView(im,new LinearLayout.LayoutParams(-1,dp(250)));section("KİŞİSEL BİLGİLER");String[][] data={{"DOĞUM TARİHİ",displayDate(val(c,"birthDate"))},{"TCKN",val(c,"tckn")},{"BAŞLANGIÇ TARİHİ",displayDate(val(c,"startDate"))},{"SPORCU TELEFONU",val(c,"athletePhone")},{"ANNE ADI",val(c,"motherName")},{"ANNE TELEFONU",val(c,"motherPhone")},{"BABA ADI",val(c,"fatherName")},{"BABA TELEFONU",val(c,"fatherPhone")},{"OKUL",val(c,"school")},{"SINIF / ŞUBE",val(c,"classBranch")},{"GRUP",val(c,"groupName")},{"AİDAT",iv(c,"scholarship")==1?"BURSLU":tl(c.getDouble(c.getColumnIndexOrThrow("monthlyFee")))},{"RAHATSIZLIKLAR",val(c,"illnesses")},{"ÖZEL NOTLAR",val(c,"notes")},{"BIRAKMA TARİHİ",displayDate(val(c,"leaveDate"))},{"BIRAKMA NEDENİ",val(c,"leaveReason")},{"TİŞÖRT",iv(c,"tshirtQty")+" ADET"},{"FORMA",iv(c,"jerseyQty")+" ADET"},{"EŞOFMAN",iv(c,"tracksuitQty")+" ADET"}};for(int i=0;i<data.length;i++){TextView rr=row(data[i][0],data[i][1],i%2==1);String p=data[i][1];if((i==3||i==5||i==7)&&p!=null&&!p.isEmpty())rr.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+p))));content.addView(rr);}c.close();section("ÖDEME GEÇMİŞİ");Cursor p=db.paymentsFor(id);boolean any=false;while(p.moveToNext()){any=true;String pd=displayDate(val(p,"paymentDate"));content.addView(row(months[p.getInt(p.getColumnIndexOrThrow("month"))-1]+" "+p.getInt(p.getColumnIndexOrThrow("year")),tl(p.getDouble(p.getColumnIndexOrThrow("amount")))+" • "+pd+" • "+val(p,"method"),any));}p.close();if(!any)content.addView(row("ÖDEME","KAYITLI ÖDEME YOK",false));section("TAKİP SÜRECİ");Cursor ev=db.eventsFor(id);int z=0;while(ev.moveToNext()){content.addView(row(displayDate(val(ev,"eventDate")),val(ev,"eventText"),(z++%2)==1));}ev.close();ArrayList<String> debts=db.debtLines(id);section("BORÇ DURUMU");if(debts.isEmpty())content.addView(row("DURUM","GEÇMİŞ DÖNEM BORCU YOK",false));else for(String d:debts)content.addView(row("BORÇ",d,true));Button edit=menu("SPORCU BİLGİLERİNİ GÜNCELLE");edit.setOnClickListener(v->{push(()->athleteDetail(id));athleteForm(id);});content.addView(edit);}
 @Override void feeScreen(){screen="FEE";clear();heading("AİDAT TAKİP");monthNav(()->feeScreen());content.addView(tv("YALNIZCA ÖDEMESİ BEKLENEN SPORCULAR GÖSTERİLİR",12,false));Cursor c=db.nonScholarshipAthletes();int count=0;while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));double due=db.expectedForMonth(id,year,month);if(due<=0||db.isPaid(id,year,month))continue;count++;Button b=menu(val(c,"name")+"   •   "+tl(due));b.setTextColor(RED);b.setOnClickListener(v->paymentDialogV23(id,due,year,month,false));content.addView(b);}c.close();if(count==0){TextView ok=tv("BU AY İÇİN BEKLEYEN AİDAT YOK",17,true);ok.setTextColor(GREEN);ok.setGravity(Gravity.CENTER);content.addView(ok);}}
 void paymentDialogV23(long id,double due,int y,int m,boolean edit){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText a=field("TUTAR",2);a.setText(""+(int)Math.round(due));EditText date=field("ÖDEME TARİHİ G/A/Y",1);date.setText(new SimpleDateFormat("dd/MM/yyyy",TR).format(new Date()));Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,payMethods));if(edit){Cursor p=db.paymentFor(id,y,m);if(p.moveToFirst()){a.setText(""+(int)Math.round(p.getDouble(p.getColumnIndexOrThrow("amount"))));date.setText(displayDate(val(p,"paymentDate")));String met=val(p,"method");for(int i=0;i<payMethods.length;i++)if(payMethods[i].equals(met))s.setSelection(i);}p.close();}l.addView(a);l.addView(date);l.addView(s);AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(edit?"AİDAT ÖDEMESİNİ GÜNCELLE":"AİDAT ÖDEMESİ EKLE").setView(l).setPositiveButton("KAYDET",(d,w)->{db.savePayment(id,y,m,num(a.getText().toString(),due),toIso(date.getText().toString()),payMethods[s.getSelectedItemPosition()]);if(screen.equals("FEE"))feeScreen();else paymentEditor(id);}).setNegativeButton("VAZGEÇ",null);if(edit)b.setNeutralButton("ÖDEMEYİ SİL",(d,w)->{db.deletePayment(id,y,m);paymentEditor(id);});b.show();}
 void paymentAthleteSearch(){screen="PAYSEARCH";clear();heading("AİDAT GÜNCELLE");EditText q=field("SPORCU ARA",1);content.addView(q);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);content.addView(r);q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){r.removeAllViews();if(s.length()<2)return;Cursor x=db.searchAthletes(up(s.toString()));while(x.moveToNext()){long id=x.getLong(x.getColumnIndexOrThrow("id"));Button athleteBtn=btn(val(x,"name"));athleteBtn.setOnClickListener(v->{push(()->paymentAthleteSearch());paymentEditor(id);});r.addView(athleteBtn);}x.close();}});}
 void paymentEditor(long id){screen="PAYEDIT";clear();heading("AİDAT GÜNCELLE");Cursor a=db.athlete(id);String name=a.moveToFirst()?val(a,"name"):"";a.close();content.addView(tv(name,21,true));Calendar start=Calendar.getInstance();start.clear();start.set(2026,Calendar.JULY,1);Calendar end=Calendar.getInstance();end.add(Calendar.MONTH,2);while(!start.after(end)){int y=start.get(Calendar.YEAR),m=start.get(Calendar.MONTH)+1;double due=db.expectedForMonth(id,y,m);if(due>0){boolean paid=db.isPaid(id,y,m);Button b=menu(months[m-1]+" "+y+" • "+(paid?"ÖDEMEYİ DÜZENLE":"ÖDEME GİR"));b.setTextColor(paid?GREEN:RED);final int yy=y,mm=m;b.setOnClickListener(v->paymentDialogV23(id,due,yy,mm,paid));content.addView(b);}start.add(Calendar.MONTH,1);}}
 @Override void attendanceMonth(String g){super.attendanceMonth(g);}
}
